#!/usr/bin/env python3
import json,re
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parents[1]
DATE='2026-09-08'; BASE='https://epochlex.justathoughtblog.org'
GLOSS='https://developers.google.com/machine-learning/glossary'
BATCH=[
{'term':'Top-p','slug':'top-p','pronunciation':'top P','definition':'A sampling method that limits the next-token choices to the smallest set of likely tokens whose cumulative probability reaches a chosen threshold p, then samples from that set.','example':'Lowering top-p narrowed the set of tokens the model considered during generation.','categories':['AI Systems & Technical Concepts'],'aliases':['Top-p sampling','Nucleus sampling'],'status':'Technical','partOfSpeech':'noun','related':['sampling','token','temperature','inference'],'sources':[{'id':'hf-top-p-sampling','type':'reference','publisher':'Hugging Face','title':'How to generate text: using different decoding methods for language generation with Transformers','published':'2020-03-01','url':'https://huggingface.co/blog/how-to-generate','supports':['definition','usage']}]},
{'term':'Speech-to-Text','slug':'speech-to-text','pronunciation':'speech tuh text','definition':'An AI speech-recognition capability that converts spoken audio into written text or a text transcription.','example':'The meeting assistant used speech-to-text to turn the recorded conversation into a searchable transcript.','categories':['AI Systems & Technical Concepts'],'aliases':['STT','Automatic speech recognition','ASR'],'status':'Established technical term','partOfSpeech':'noun','related':['artificial-intelligence','natural-language-processing'],'sources':[{'id':'google-cloud-stt','type':'primary','publisher':'Google Cloud','title':'Cloud Speech-to-Text documentation','published':None,'url':'https://docs.cloud.google.com/speech-to-text/docs','supports':['definition','usage']}]},
{'term':'Text-to-Speech','slug':'text-to-speech','pronunciation':'text tuh speech','definition':'An AI speech-synthesis capability that converts written text into spoken audio, often using generated voices.','example':'The accessibility feature used text-to-speech to read the generated answer aloud.','categories':['AI Systems & Technical Concepts'],'aliases':['TTS','Speech synthesis'],'status':'Established technical term','partOfSpeech':'noun','related':['artificial-intelligence','natural-language-processing'],'sources':[{'id':'google-cloud-tts','type':'primary','publisher':'Google Cloud','title':'Cloud Text-to-Speech documentation','published':None,'url':'https://docs.cloud.google.com/text-to-speech/docs','supports':['definition','usage']}]},
{'term':'Text-to-Video','slug':'text-to-video','pronunciation':'text tuh VID-ee-oh','definition':'A generative AI task or model capability that creates video from a text prompt or description.','example':'The creative team used a text-to-video model to generate a short scene from a written prompt.','categories':['AI Systems & Technical Concepts'],'aliases':['Text-to-video generation','T2V'],'status':'Established emerging technical term','partOfSpeech':'noun','related':['artificial-intelligence','synthetic-content'],'sources':[{'id':'hf-text-to-video','type':'reference','publisher':'Hugging Face','title':'Text-to-Video','published':None,'url':'https://huggingface.co/tasks/text-to-video','supports':['definition','usage']}]},
{'term':'Loss Function','slug':'loss-function','pronunciation':'lawss FUNK-shun','definition':'A mathematical function that measures how far a model’s predictions are from desired or reference outcomes, producing a loss value that training commonly seeks to minimize.','example':'The training run used a loss function to quantify prediction error after each batch.','categories':['AI Systems & Technical Concepts'],'aliases':['Objective loss function'],'status':'Established technical term','partOfSpeech':'noun','related':['training-data','parameters','fine-tuning'],'sources':[{'id':'google-ml-loss-function','type':'reference','publisher':'Google for Developers','title':'Machine Learning Glossary','published':'2026','url':GLOSS,'supports':['definition','usage']}]},
{'term':'Gradient Descent','slug':'gradient-descent','pronunciation':'GRAY-dee-unt dih-SENT','definition':'An optimization method that iteratively adjusts model parameters in directions that reduce a loss function.','example':'Gradient descent updated the model weights repeatedly as training worked to reduce loss.','categories':['AI Systems & Technical Concepts'],'aliases':[],'status':'Established technical term','partOfSpeech':'noun','related':['loss-function','parameters','training-data'],'sources':[{'id':'google-ml-gradient-descent','type':'reference','publisher':'Google for Developers','title':'Machine Learning Glossary','published':'2026','url':GLOSS,'supports':['definition','usage']}]},
{'term':'Backpropagation','slug':'backpropagation','pronunciation':'bak-PROP-uh-GAY-shun','definition':'The algorithm used in neural-network training to calculate how changes in model parameters affect loss, allowing gradients to be propagated backward through the network so the parameters can be updated.','example':'Backpropagation calculated the gradients needed to update the neural network during training.','categories':['AI Systems & Technical Concepts'],'aliases':['Backprop'],'status':'Established technical term','partOfSpeech':'noun','related':['gradient-descent','loss-function','neural-network','parameters'],'sources':[{'id':'google-ml-backprop','type':'reference','publisher':'Google for Developers','title':'Machine Learning Glossary','published':'2026','url':GLOSS,'supports':['definition','usage']}]},
{'term':'Overfitting','slug':'overfitting','pronunciation':'OH-ver-FIT-ing','definition':'A training failure in which a model fits its training data so closely that it performs poorly on new or unseen data.','example':'The widening gap between training and validation performance was a sign of overfitting.','categories':['AI Systems & Technical Concepts'],'aliases':['Overfit'],'status':'Established technical term','partOfSpeech':'noun','related':['training-data','fine-tuning','loss-function'],'sources':[{'id':'google-ml-overfitting','type':'reference','publisher':'Google for Developers','title':'Machine Learning Glossary','published':'2026','url':GLOSS,'supports':['definition','usage']}]},
{'term':'Underfitting','slug':'underfitting','pronunciation':'UN-der-FIT-ing','definition':'A training failure in which a model does not capture enough of the structure or complexity in the training data to make useful predictions.','example':'The model was underfitting because it performed poorly even on the examples it had been trained on.','categories':['AI Systems & Technical Concepts'],'aliases':['Underfit'],'status':'Established technical term','partOfSpeech':'noun','related':['training-data','fine-tuning','loss-function'],'sources':[{'id':'google-ml-underfitting','type':'reference','publisher':'Google for Developers','title':'Machine Learning Glossary','published':'2026','url':GLOSS,'supports':['definition','usage']}]},
{'term':'Unsupervised Learning','slug':'unsupervised-learning','pronunciation':'un-SOO-per-vyz-d LUR-ning','definition':'A machine-learning approach that trains on data without supplied target labels in order to discover patterns, structure, groupings, or useful representations.','example':'The team used unsupervised learning to find clusters in customer behavior without predefined category labels.','categories':['AI Systems & Technical Concepts'],'aliases':['Unsupervised machine learning'],'status':'Established technical term','partOfSpeech':'noun','related':['artificial-intelligence','training-data','neural-network'],'sources':[{'id':'google-ml-unsupervised','type':'reference','publisher':'Google for Developers','title':'Machine Learning Glossary','published':'2026','url':GLOSS,'supports':['definition','usage']}]}
]

def page(t):
 term=escape(t['term']); d=escape(t['definition'],quote=True); p=escape(t['pronunciation']); slug=t['slug']; url=f'{BASE}/terms/{slug}/'
 ld=json.dumps({'@context':'https://schema.org','@type':'DefinedTerm','name':t['term'],'description':t['definition'],'url':url,'inDefinedTermSet':BASE+'/','inLanguage':'en'},ensure_ascii=False)
 return f'''<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="color-scheme" content="light dark">\n  <title>{term} | EpochLex</title>\n  <meta name="description" content="{d}">\n  <link rel="canonical" href="{url}">\n  <meta property="og:site_name" content="EpochLex">\n  <meta property="og:title" content="{term} | EpochLex">\n  <meta property="og:description" content="{d}">\n  <meta property="og:type" content="article">\n  <meta property="og:url" content="{url}">\n  <meta name="twitter:card" content="summary">\n  <meta name="twitter:title" content="{term} | EpochLex">\n  <meta name="twitter:description" content="{d}">\n  <script type="application/ld+json">{ld}</script>\n  <script>(()=>{{try{{const saved=localStorage.getItem("ai-era-theme");const systemDark=window.matchMedia("(prefers-color-scheme: dark)").matches;document.documentElement.dataset.theme=saved||(systemDark?"dark":"light");}}catch(_){{document.documentElement.dataset.theme="light";}}}})();</script>\n  <link rel="stylesheet" href="../../assets/css/styles.css">\n  <link rel="stylesheet" href="../../assets/css/term-pages.css">\n  <link rel="stylesheet" href="../../assets/css/brand-theme.css">\n</head>\n<body>\n<header class="site-header"><div class="shell header-inner"><a class="brand" href="../../" aria-label="EpochLex home"><span class="brand-lockup" aria-hidden="true"><img class="brand-lockup-image brand-lockup-light" src="../../assets/brand/epochlex/epochlex-logo-horizontal-light.png" alt=""><img class="brand-lockup-image brand-lockup-dark" src="../../assets/brand/epochlex/epochlex-logo-horizontal-dark.png" alt=""></span><span class="sr-only">EpochLex</span></a><nav class="primary-nav" aria-label="Primary navigation"><a class="active" href="../../">Browse</a><a href="../../categories.html">Categories</a><a href="../../about.html">About</a><a href="../../contribute.html">Contribute</a><a href="../../methodology.html">Methodology</a></nav><button id="theme-toggle" class="theme-toggle" type="button" aria-label="Switch color theme" title="Switch color theme"><span class="sun" aria-hidden="true">☼</span><span class="toggle-track"><span class="toggle-knob"></span></span><span class="moon" aria-hidden="true">☾</span></button></div></header>\n<main id="term-page" class="term-page shell" data-term-slug="{slug}"><div id="term-fallback" class="term-fallback"><nav class="term-breadcrumb" aria-label="Breadcrumb"><a href="../../">Browse</a><span aria-hidden="true">/</span><span>{term}</span></nav><p class="eyebrow">EpochLex entry</p><h1>{term}</h1><p class="fallback-pronunciation">{p}</p><p class="fallback-definition">{escape(t['definition'])}</p></div></main>\n<footer class="site-footer"><div class="shell footer-inner"><span class="footer-mark" aria-hidden="true">◎</span><p><strong>EpochLex · Dictionary of the AI Era</strong><br>Vibe coded · Human-directed · AI-assisted · Human-reviewed</p><p class="footer-license">Code: MIT · Content: CC BY 4.0</p></div></footer><script src="../../assets/js/app.js"></script><script src="../../assets/js/term-page.js"></script>\n</body>\n</html>\n'''

terms_path=ROOT/'data/terms.json'; terms=json.loads(terms_path.read_text()); existing={x['slug'] for x in terms}
for b in BATCH:
 if b['slug'] in existing: raise SystemExit(f'already published: {b["slug"]}')
 rec={k:v for k,v in b.items() if k not in ('related','sources')}; rec.update({'added':DATE,'lastReviewed':DATE,'sources':[]}); terms.append(rec)
terms.sort(key=lambda x:x['term'].lower()); terms_path.write_text(json.dumps(terms,ensure_ascii=False,separators=(',',':'))+'\n')

prov_path=ROOT/'data/provenance.json'; prov=json.loads(prov_path.read_text())
for b in BATCH: prov[b['slug']]={'researchStatus':'pending','origin':None,'firstKnownUse':None,'history':[],'relatedTerms':b['related'],'sources':b['sources']}
# Sampling can now point directly to Top-p because Top-p is published in this batch.
if 'sampling' in prov:
 rel=prov['sampling'].get('relatedTerms',[])
 if 'top-p' not in rel: rel.append('top-p')
 prov['sampling']['relatedTerms']=rel
prov_path.write_text(json.dumps(prov,ensure_ascii=False,indent=2)+'\n')

for b in BATCH:
 p=ROOT/'terms'/b['slug']; p.mkdir(parents=True,exist_ok=True); (p/'index.html').write_text(page(b))

cand=ROOT/'docs/CORPUS-CANDIDATES.md'; text=cand.read_text()
for b in BATCH: text=re.sub(r'^- '+re.escape(b['term'])+r'\s*$','',text,flags=re.M)
text=re.sub(r'\n{3,}','\n\n',text); start=text.index('## Repository roadmap candidates'); end=text.index('## Related documentation'); count=sum(1 for line in text[start:end].splitlines() if line.startswith('- ')); text=re.sub(r'\*\*Current unpublished inventory: \d+ candidates\.\*\*',f'**Current unpublished inventory: {count} candidates.**',text,count=1); cand.write_text(text)

audit=ROOT/'docs/CORPUS-AUDIT-2026-09.md'; a=audit.read_text(); section='\n## Publish — Batch C (published September 8, 2026)\n\n'
for b in BATCH:
 src='; '.join(f"[{s['publisher']}: {s['title']}]({s['url']})" for s in b['sources']); section+=f"### {b['term']}\n\n**Why publish:** {b['definition']}\n\n**Usage evidence:** {src}\n\n**Provenance state:** `pending` — meaning/usage evidence is recorded; origin, first-known-use, and fuller history research remain open.\n\n"
a=a.replace('## Publish — next qualified group',section+'## Publish — next qualified group')
for b in BATCH: a=re.sub(r'^- '+re.escape(b['term'])+r'\s*$','',a,flags=re.M)
a=a.replace('This audit has now published 18 candidates across Batches A and B and added 172 new research candidates.','This audit has now published 28 candidates across Batches A, B, and C and added 172 new research candidates.')
audit.write_text(re.sub(r'\n{3,}','\n\n',a))

road=ROOT/'docs/ROADMAP.md'; r=road.read_text(); r=r.replace('- 140 published dictionary entries;','- 150 published dictionary entries;').replace('- 122 researched provenance records and 18 pending provenance records in the current published corpus;','- 122 researched provenance records and 28 pending provenance records in the current published corpus;'); road.write_text(r)

site=ROOT/'sitemap.xml'; sm=site.read_text(); blocks=''.join(f'  <url>\n    <loc>{BASE}/terms/{b["slug"]}/</loc>\n    <lastmod>{DATE}</lastmod>\n  </url>\n' for b in BATCH); sm=sm.replace('</urlset>',blocks+'</urlset>'); site.write_text(sm)

terms=json.loads(terms_path.read_text()); prov=json.loads(prov_path.read_text()); slugs={x['slug'] for x in terms}
assert len(terms)==150, len(terms); assert slugs==set(prov); assert sum(1 for x in prov.values() if x.get('researchStatus')=='pending')==28
for record in prov.values():
 for slug in record.get('relatedTerms',[]): assert slug in slugs, f'unpublished related term: {slug}'
for b in BATCH: assert (ROOT/'terms'/b['slug']/'index.html').exists()
assert count==723, count
print('Validated 150 published entries, 28 pending provenance records, 723 candidates, and related-term parity.')